<?php /** @var list<array<string,mixed>> $rows */ /** @var int $total */ /** @var int $page */ /** @var array<string,string> $f */ /** @var array<string,string> $statuses */ ?>
<div class="page-head"><div><p class="eyebrow">Website</p><h1>Job applications</h1></div><a class="btn btn-ghost" href="/admin/site/jobs">Openings</a></div>
<p class="muted">Applications from the Careers page. They contain personal details: share them only with people who need them. Receiving an application promises nothing to the applicant.</p>
<form method="get" class="toolbar"><div class="field"><label for="q">Search</label><input id="q" name="q" value="<?= e($f['q']) ?>" maxlength="60" placeholder="Name, email, reference"></div>
    <div class="field"><label for="st">Status</label><select id="st" name="status"><option value="">Active</option><?php foreach ($statuses as $k => $l) : ?><option value="<?= e($k) ?>"<?= $f['status'] === $k ? ' selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div><div class="field"><button class="btn btn-ghost" type="submit">Filter</button></div></form>
<div class="table-wrap"><table class="table"><thead><tr><th>Reference</th><th>Applicant</th><th>Role</th><th>Status</th><th>Received</th></tr></thead><tbody>
<?php foreach ($rows as $r) : ?><tr><td><a href="/admin/careers/<?= e($r['public_id']) ?>"><?= e($r['reference']) ?></a></td><td><?= e($r['full_name']) ?><br><span class="muted small"><?= e($r['email']) ?></span></td><td><?= e($r['role_applied']) ?><?= $r['has_file'] ? ' <span class="badge">file</span>' : '' ?></td><td><span class="badge badge-sys-<?= $r['status'] === 'new' ? 'warn' : 'ok' ?>"><?= e($statuses[$r['status']] ?? $r['status']) ?></span></td><td><?= e(local_time((string) $r['created_at'])) ?></td></tr><?php endforeach; ?>
<?php if ($rows === []) : ?><tr><td colspan="5" class="muted">No applications.</td></tr><?php endif; ?></tbody></table></div>
